import struct, sys, os

class ISO:
    def __init__(self, path):
        self.f = open(path, 'rb')
        self.f.seek(16*2048)
        pvd = self.f.read(2048)
        if pvd[0] != 1:
            raise Exception("No PVD found (maybe El Torito/hybrid?)")
        # logical block size at offset 128 (both-endian, little at 128)
        self.bs = struct.unpack('<H', pvd[128:130])[0]
        root_rec = pvd[156:156+34]
        self.root = self._parse_rec(root_rec)
    def _parse_rec(self, rec):
        lba = struct.unpack('<I', rec[2:6])[0]
        size = struct.unpack('<I', rec[10:14])[0]
        flags = rec[25]
